// In your ViewModel / Notifier / BLoC:
class CartModel extends ChangeNotifier {
  Future<bool> placeOrder() async {
    final order = createOrder(cart.items);
    final success = await ApiService.submitOrder(order);
    if (success) clearCart(); // State change logic
    notifyListeners();
    return success;
  }
}

// In your widget:
class OrderButton extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    // Read the model to call methods.
    final cartModel = context.read<CartModel>();

    return ElevatedButton(
      onPressed: () async {
        final success = await cartModel.placeOrder();
        if (success) {
           Navigator.push(context, '/success');
        } else {
           ScaffoldMessenger.of(context).showSnackBar(...);
        }
      },
      child: Text('Place Order'),
    );
  }
}

