// An immutable User state object
@immutable
class User {
  final String name;
  final int age;

  const User({required this.name, required this.age});

  // A 'copyWith' method makes creating new instances easy.
  User copyWith({String? name, int? age}) {
    return User(
      name: name ?? this.name,
      age: age ?? this.age,
    );
  }
}
